package dev.apogee.client.model;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.PartDefinition;

/**
 * Mantis Blade cubes, in texels (half a model pixel): the steel mechanism and the skin covers.
 * Generated by tools/mantis_model.py together with textures/entity/mantis_blades*.png; edit the
 * script and run it again rather than editing this file, so geometry and UVs stay in sync.
 */
final class MantisMechanismMesh {
    static final int TEXTURE_SIZE = 128;

    private MantisMechanismMesh() {
    }

    @SuppressWarnings("unused")
    static void build(PartDefinition parent) {
        PartDefinition housing = parent.addOrReplaceChild("housing", CubeListBuilder.create()
                        .texOffs(0, 0).addBox(-5.0F, 6.0F, -3.0F, 1.0F, 10.0F, 1.0F)
                        .texOffs(4, 0).addBox(-5.0F, 7.0F, -1.0F, 1.0F, 8.0F, 1.0F)
                        .texOffs(8, 0).addBox(4.0F, 6.0F, -3.0F, 1.0F, 10.0F, 1.0F)
                        .texOffs(12, 0).addBox(4.0F, 7.0F, -1.0F, 1.0F, 8.0F, 1.0F)
                        .texOffs(16, 0).addBox(-4.0F, 6.0F, -5.0F, 1.0F, 10.0F, 1.0F)
                        .texOffs(20, 0).addBox(3.0F, 6.0F, -5.0F, 1.0F, 10.0F, 1.0F)
                        .texOffs(24, 0).addBox(-6.0F, 5.0F, -6.0F, 2.0F, 2.0F, 5.0F)
                        .texOffs(38, 0).addBox(4.0F, 5.0F, -6.0F, 2.0F, 2.0F, 5.0F)
                        .texOffs(52, 0).addBox(-6.0F, 10.0F, -6.0F, 2.0F, 2.0F, 5.0F)
                        .texOffs(66, 0).addBox(4.0F, 10.0F, -6.0F, 2.0F, 2.0F, 5.0F)
                        .texOffs(80, 0).addBox(-3.0F, 15.0F, -6.0F, 6.0F, 2.0F, 2.0F),
                PartPose.offset(0.0F, 0.0F, 0.0F));
        PartDefinition cover_left = housing.addOrReplaceChild("cover_left", CubeListBuilder.create()
                        .texOffs(96, 0).addBox(0.0F, 0.0F, -1.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(-4.0F, 7.0F, -6.0F));
        PartDefinition cover_right = housing.addOrReplaceChild("cover_right", CubeListBuilder.create()
                        .texOffs(106, 0).addBox(-4.0F, 0.0F, -1.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(4.0F, 7.0F, -6.0F));
        PartDefinition link_lower = housing.addOrReplaceChild("link_lower", CubeListBuilder.create()
                        .texOffs(116, 0).addBox(-2.0F, 0.0F, -1.0F, 1.0F, 7.0F, 2.0F)
                        .texOffs(122, 0).addBox(1.0F, 0.0F, -1.0F, 1.0F, 7.0F, 2.0F)
                        .texOffs(0, 11).addBox(-2.0F, 2.0F, -2.0F, 1.0F, 4.0F, 1.0F)
                        .texOffs(4, 11).addBox(1.0F, 2.0F, -2.0F, 1.0F, 4.0F, 1.0F)
                        .texOffs(8, 11).addBox(-3.0F, 6.0F, -1.0F, 1.0F, 2.0F, 2.0F)
                        .texOffs(14, 11).addBox(2.0F, 6.0F, -1.0F, 1.0F, 2.0F, 2.0F),
                PartPose.offset(0.0F, 15.0F, -5.0F));
        PartDefinition link_upper = link_lower.addOrReplaceChild("link_upper", CubeListBuilder.create()
                        .texOffs(20, 11).addBox(-3.0F, 0.0F, -1.0F, 1.0F, 6.0F, 2.0F)
                        .texOffs(26, 11).addBox(2.0F, 0.0F, -1.0F, 1.0F, 6.0F, 2.0F)
                        .texOffs(32, 11).addBox(-3.0F, 1.0F, -2.0F, 1.0F, 4.0F, 1.0F)
                        .texOffs(36, 11).addBox(2.0F, 1.0F, -2.0F, 1.0F, 4.0F, 1.0F),
                PartPose.offset(0.0F, 7.0F, 0.0F));
        PartDefinition blade = link_upper.addOrReplaceChild("blade", CubeListBuilder.create()
                        .texOffs(40, 11).addBox(-2.0F, -4.0F, -2.0F, 4.0F, 4.0F, 3.0F)
                        .texOffs(54, 11).addBox(-1.0F, -6.0F, -1.0F, 2.0F, 2.0F, 2.0F)
                        .texOffs(62, 11).addBox(-1.0F, -4.0F, 1.0F, 2.0F, 2.0F, 1.0F)
                        .texOffs(68, 11).addBox(-1.0F, 0.0F, -1.0F, 2.0F, 14.0F, 2.0F)
                        .texOffs(76, 11).addBox(-1.0F, 2.0F, -2.0F, 2.0F, 10.0F, 1.0F),
                PartPose.offset(0.0F, 6.0F, 0.0F));
        PartDefinition edge = blade.addOrReplaceChild("edge", CubeListBuilder.create()
                        .texOffs(82, 11).addBox(-0.5F, 0.0F, -1.0F, 1.0F, 22.0F, 2.0F)
                        .texOffs(88, 11).addBox(-0.5F, 1.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(92, 11).addBox(-0.5F, 3.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(96, 11).addBox(-0.5F, 5.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(100, 11).addBox(-0.5F, 7.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(104, 11).addBox(-0.5F, 9.0F, 1.0F, 1.0F, 1.0F, 1.0F)
                        .texOffs(108, 11).addBox(-0.5F, 22.0F, -1.0F, 1.0F, 2.0F, 1.0F)
                        .texOffs(112, 11).addBox(-0.5F, 24.0F, -1.0F, 1.0F, 1.0F, 1.0F),
                PartPose.offset(0.0F, 14.0F, 0.0F));
    }

    /** Skin tops of the wrist covers, one pair per arm, read from the wearer's 64x64 skin. */
    static void buildSkinCovers(PartDefinition parent) {
        PartDefinition rightArm = parent.addOrReplaceChild("right_arm", CubeListBuilder.create(), PartPose.ZERO);
        rightArm.addOrReplaceChild("cover_left", CubeListBuilder.create()
                        .texOffs(87, 50).addBox(0.0F, 0.0F, -2.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(-4.0F, 7.0F, -6.0F));
        rightArm.addOrReplaceChild("cover_right", CubeListBuilder.create()
                        .texOffs(91, 50).addBox(-4.0F, 0.0F, -2.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(4.0F, 7.0F, -6.0F));
        PartDefinition leftArm = parent.addOrReplaceChild("left_arm", CubeListBuilder.create(), PartPose.ZERO);
        leftArm.addOrReplaceChild("cover_left", CubeListBuilder.create()
                        .texOffs(71, 114).addBox(0.0F, 0.0F, -2.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(-4.0F, 7.0F, -6.0F));
        leftArm.addOrReplaceChild("cover_right", CubeListBuilder.create()
                        .texOffs(75, 114).addBox(-4.0F, 0.0F, -2.0F, 4.0F, 7.0F, 1.0F),
                PartPose.offset(4.0F, 7.0F, -6.0F));
    }
}
